post_build.linux:
find . -maxdepth 2 -name '*.AppImage.zsync' -not -path './src-tauri/target/*' | while read -r z; do dest=$(dirname "$(find src-tauri/target -path '*/bundle/appimage/*.AppImage' | head -n 1)"); mv "$z" "$dest/"; done
case "$FORMCOMPILER_PLATFORM" in
  linux-arm64) arch=arm64; debarch=arm64 ;;
  *) arch=x64; debarch=amd64 ;;
esac
python3 setup/package_desktop.py linux-tar --arch "$arch" --debarch "$debarch"

post_build.windows:
case "$FORMCOMPILER_PLATFORM" in
  windows-x86) arch=x86 ;;
  windows-arm64) arch=arm64 ;;
  *) arch=x64 ;;
esac
python setup/package_desktop.py portable-windows --arch "$arch" --release-dir "$FORMCOMPILER_RELEASE_DIR"
if [ "$arch" != x86 ]; then python setup/package_desktop.py msix --arch "$arch"; fi
